23	        super(secret, algorithm, digits);
24	        setPeriod(period);
25	    }
26	
27	    @Override
28	    public String getOtp() {
29	        try {
30	            OTP otp = TOTP.generateOTP(getSecret(), getAlgorithm(true), getDigits(), getPeriod());
31	            return otp.toString();
32	        } catch (InvalidKeyException | NoSuchAlgorithmException e) {
33	            throw new RuntimeException(e);
34	        }
35	    }
36	
37	    @Override
38	    public String getType() {
39	        return ID;
40	    }
41	
42	    @Override
43	    public JSONObject toJson() {
44	        JSONObject obj = super.toJson();
45	        try {
46	            obj.put("period", getPeriod());
47	        } catch (JSONException e) {
48	            throw new RuntimeException(e);
49	        }
50	        return obj;
51	    }
52	
53	    public int getPeriod() {
54	        return _period;
55	    }
56	
57	    public static boolean isPeriodValid(int period) {
58	        if (period <= 0) {
59	            return false;
60	        }
61	
62	        // check for the possibility of an overflow when converting to milliseconds
63	        return period <= Integer.MAX_VALUE / 1000;
64	    }
65	
66	    public void setPeriod(int period) throws OtpInfoException {
67	        if (!isPeriodValid(period)) {
68	            throw new OtpInfoException(String.format("bad period: %d", period));
69	        }
70	        _period = period;
71	    }
72	
73	    public long getMillisTillNextRotation() {
74	        return TotpInfo.getMillisTillNextRotation(_period);
75	    }
76	
77	    public static long getMillisTillNextRotation(int period) {
78	        long p = period * 1000;
79	        return p - (System.currentTimeMillis() % p);
80	    }
