private void refresh() {
    // calculate the current progress the bar should start at
    int maxProgress = getMax();
    long periodMillis = _period * 1000L;
    long millisTillRotation = TotpInfo.getMillisTillNextRotation(_period);
    int currentProgress = (int) (maxProgress * ((double) millisTillRotation / periodMillis));

    // the progress bar is animated in parts of (at most) one second, so find the
    // amount of milliseconds till rotation the current animation should end at and
    // translate that to a progress value
    // note: this calculation is done in the time domain instead of the progress
    // domain on purpose, as the number of progress units per second may be less
    // than one for large periods
    long animEndMillisTillRotation = ((millisTillRotation - 1) / 1000) * 1000;
    int animEnd = (int) (maxProgress * ((double) animEndMillisTillRotation / periodMillis));

    // start progress animation, compensating for any changes to the animator duration scale settings
    long realAnimDuration = millisTillRotation - animEndMillisTillRotation;
    long animDuration = _animDurationScale > 0 ? (long) (realAnimDuration / _animDurationScale) : 0;
    ObjectAnimator animation = ObjectAnimator.ofInt(this, "progress", currentProgress, animEnd);
    animation.setDuration(animDuration);
    animation.setInterpolator(new LinearInterpolator());
    animation.start();

    // the animation only lasts for (at most) one second, so restart it after that
    _handler.postDelayed(this::refresh, realAnimDuration);
}

