public class Sim2 {
    static long getMillisTillNextRotation(int period) {
        long p = period * 1000L;
        return p - (System.currentTimeMillis() % p);
    }
    // mirrors the new TotpProgressBar.refresh()
    static void refreshNew(int maxProgress, int period, long now, float scale) {
        long periodMillis = period * 1000L;
        long millisTillRotation = periodMillis - (now % periodMillis);
        int currentProgress = (int) (maxProgress * ((double) millisTillRotation / periodMillis));
        long animEndMillis = ((millisTillRotation - 1) / 1000) * 1000;
        int animEnd = (int) (maxProgress * ((double) animEndMillis / periodMillis));
        long realAnimDuration = millisTillRotation - animEndMillis;
        long animDuration = scale > 0 ? (long) (realAnimDuration / scale) : 0;
        if (realAnimDuration < 1 || realAnimDuration > 1000)
            throw new AssertionError("bad repost delay " + realAnimDuration);
        if (animEnd > currentProgress || animEnd < 0 || currentProgress > maxProgress)
            throw new AssertionError("bad progress " + currentProgress + "->" + animEnd);
        if (animDuration < 0) throw new AssertionError("bad duration " + animDuration);
    }
    public static void main(String[] a) {
        int[] periods = {1, 2, 5, 10, 30, 60, 90, 120, 3600, 4999, 5000, 5001, 9999, 100000, 2147483};
        float[] scales = {1.0f, 0.5f, 2.0f, 0.0f};
        long base = System.currentTimeMillis();
        for (int p : periods)
            for (float s : scales)
                for (long d = 0; d < 20000; d += 37)
                    refreshNew(5000, p, base + d, s);
        System.out.println("all combinations OK (no crash, sane values)");

        // show a full walk-through for period 9999
        long now = base;
        for (int i = 0; i < 3; i++) {
            long periodMillis = 9999 * 1000L;
            long m = periodMillis - (now % periodMillis);
            long e = ((m - 1) / 1000) * 1000;
            System.out.printf("millisTillRotation=%d -> progress %d..%d, repost in %dms%n",
                m, (int)(5000*((double)m/periodMillis)), (int)(5000*((double)e/periodMillis)), m - e);
            now += (m - e);
        }
        System.out.println("period=1 millisTillRotation=" + getMillisTillNextRotation(1));
        System.out.println("period=2147483 millisTillRotation=" + getMillisTillNextRotation(2147483));
    }
}
